const Api=function(){const inFlight=new Map;const DEDUPE_POST_ACTIONS=["getConversation","getCustomerInbox","getCustomerProfile","listCustomerOrders","listCustomerBookings","getUnreadCount","getVendorConversations"];function share(key,run){const existing=inFlight.get(key);if(existing)return existing;const promise=run().finally(()=>{if(inFlight.get(key)===promise)inFlight.delete(key)});inFlight.set(key,promise);return promise}const UPDATING="This part of Mwakete is being updated. Please try again in a little while.";function friendly(res){if(res&&res.ok===false&&/^Unknown action: /.test(String(res.error||""))){return Object.assign({},res,{error:UPDATING,outdated:true})}return res}function assertConfigured(){if(!APP_CONFIG.APPS_SCRIPT_URL||APP_CONFIG.APPS_SCRIPT_URL.indexOf("PASTE_YOUR")===0){throw new Error("This shop is not connected yet. Ask the site owner to finish setup (see README.md).")}}async function get(action,params){assertConfigured();const url=new URL(APP_CONFIG.APPS_SCRIPT_URL);url.searchParams.set("action",action);Object.entries(params||{}).forEach(([key,value])=>{if(value!==undefined&&value!==null)url.searchParams.set(key,value)});const href=url.toString();return share("GET "+href,async()=>{try{const res=await fetch(href,{method:"GET"});return friendly(await res.json())}catch(err){return{ok:false,error:"Network error - please check your connection and try again."}}})}async function post(action,payload){assertConfigured();const body=JSON.stringify(Object.assign({action:action},payload||{}));const send=async()=>{try{const res=await fetch(APP_CONFIG.APPS_SCRIPT_URL,{method:"POST",headers:{"Content-Type":"text/plain;charset=utf-8"},body:body});return friendly(await res.json())}catch(err){return{ok:false,error:"Network error - please check your connection and try again."}}};if(DEDUPE_POST_ACTIONS.indexOf(action)===-1)return send();return share("POST "+body,send)}const KEPT_PREFIX="skiri_kept:";const MAX_KEPT=12;const MAX_AGE_MS=7*864e5;function recall(key){try{const v=JSON.parse(localStorage.getItem(KEPT_PREFIX+key));return v&&v.data&&Date.now()-v.t<MAX_AGE_MS?v.data:null}catch(e){return null}}function remember(key,data){try{const json=JSON.stringify(data);const old=localStorage.getItem(KEPT_PREFIX+key);if(old&&old.indexOf(json)!==-1&&old.length-json.length<40)return false;localStorage.setItem(KEPT_PREFIX+key,JSON.stringify({t:Date.now(),data:data}));const keys=[];for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(k&&k.indexOf(KEPT_PREFIX)===0)keys.push(k)}if(keys.length>MAX_KEPT){keys.map(k=>{try{return[k,JSON.parse(localStorage.getItem(k)).t||0]}catch(e){return[k,0]}}).sort((a,b)=>a[1]-b[1]).slice(0,keys.length-MAX_KEPT).forEach(x=>localStorage.removeItem(x[0]))}}catch(e){}return true}function forget(prefix){try{const drop=[];for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(k&&k.indexOf(KEPT_PREFIX+(prefix||""))===0)drop.push(k)}drop.forEach(k=>localStorage.removeItem(k))}catch(e){}}return{get:get,post:post,recall:recall,remember:remember,forget:forget}}();